// pages/dashboard.jsx
import { useEffect, useState } from "react";
import { BASE_URL } from "../utils/api";
import toast from "react-hot-toast";

export default function Dashboard() {
  const [user, setUser] = useState(null);
  const [pickups, setPickups] = useState([]);
  const [loading, setLoading] = useState(true);

  // 🔥 Scroll function
  const scrollToSection = (id) => {
    document.getElementById(id)?.scrollIntoView({
      behavior: "smooth",
    });
  };

  // 🔥 Fetch dashboard data
  useEffect(() => {
    const fetchDashboard = async () => {
      try {
        const res = await fetch(`${BASE_URL}/api/dashboard`, {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("trashverse_token")}`,
          },
        });

        const data = await res.json();

        if (!res.ok) {
          return toast.error(data.message || "Failed to load dashboard");
        }

        setUser(data.user);
        setPickups(data.pickups || []);
      } catch (err) {
        toast.error("Network error");
      } finally {
        setLoading(false);
      }
    };

    fetchDashboard();
  }, []);

  return (
    <div className="bg-gray-100 min-h-screen pb-10">

      {/* 🔥 HEADER */}
      <div className="bg-green-600 text-white px-5 pt-5 pb-6 rounded-b-3xl shadow-md">

        {/* TOP BAR */}
        <div className="flex justify-between items-center">
          <div>
            <h1 className="text-lg font-semibold">
              Hi, {user?.name || "User"} 👋
            </h1>
            <p className="text-xs opacity-80">Welcome back</p>
          </div>

          <div className="flex items-center gap-3">
            {/* 🔔 Notification */}
            <div className="relative cursor-pointer">
              <span className="text-xl">🔔</span>
              <span className="absolute top-0 right-0 w-2 h-2 bg-red-500 rounded-full"></span>
            </div>

            {/* 👤 Avatar */}
            {user?.photo ? (
              <img
                src={user.photo}
                className="w-9 h-9 rounded-full object-cover"
              />
            ) : (
              <div className="w-9 h-9 rounded-full bg-white flex items-center justify-center text-green-600 font-bold">
                {user?.name ? user.name.charAt(0) : "U"}
              </div>
            )}
          </div>
        </div>

        {/* 💰 Earnings */}
        <div className="mt-4 bg-white text-black p-4 rounded-2xl shadow-sm">
          <p className="text-gray-500 text-sm">Total Earnings</p>
          <h2 className="text-2xl font-bold text-green-600">
            ₦{user?.earnings || 0}
          </h2>
        </div>

        {/* ⚡ QUICK ACTIONS */}
        <div className="grid grid-cols-4 gap-4 mt-5 text-center">

          <div
            onClick={() => scrollToSection("schedule")}
            className="flex flex-col items-center cursor-pointer active:scale-95 transition"
          >
            <div className="bg-white text-green-600 w-10 h-10 flex items-center justify-center rounded-full shadow">
              ♻️
            </div>
            <p className="text-xs mt-1">Pickup</p>
          </div>

          <div
            onClick={() => scrollToSection("stats")}
            className="flex flex-col items-center cursor-pointer active:scale-95 transition"
          >
            <div className="bg-white text-green-600 w-10 h-10 flex items-center justify-center rounded-full shadow">
              💰
            </div>
            <p className="text-xs mt-1">Stats</p>
          </div>

          <div
            onClick={() => scrollToSection("history")}
            className="flex flex-col items-center cursor-pointer active:scale-95 transition"
          >
            <div className="bg-white text-green-600 w-10 h-10 flex items-center justify-center rounded-full shadow">
              📊
            </div>
            <p className="text-xs mt-1">History</p>
          </div>

          <div
            onClick={() => scrollToSection("pricing")}
            className="flex flex-col items-center cursor-pointer active:scale-95 transition"
          >
            <div className="bg-white text-green-600 w-10 h-10 flex items-center justify-center rounded-full shadow">
              ⚙️
            </div>
            <p className="text-xs mt-1">Pricing</p>
          </div>

        </div>
      </div>

      {/* 🔥 ACTION BUTTON */}
      <div id="schedule" className="px-4 mt-6">
        <button className="w-full bg-green-600 text-white py-3 rounded-xl font-semibold shadow hover:bg-green-700 transition">
          ♻️ Schedule Pickup
        </button>
      </div>

      {/* 🔥 STATS */}
      <div id="stats" className="grid grid-cols-2 gap-4 px-4 mt-6">
        <div className="bg-white p-4 rounded-2xl shadow-sm">
          <p className="text-gray-500 text-sm">Pickups</p>
          <h2 className="text-xl font-bold">{pickups.length}</h2>
        </div>

        <div className="bg-white p-4 rounded-2xl shadow-sm">
          <p className="text-gray-500 text-sm">Recycled</p>
          <h2 className="text-xl font-bold">
            {pickups.reduce((acc, p) => acc + (p.kg || 0), 0)}kg
          </h2>
        </div>
      </div>

      {/* 🔥 CHART */}
      <div className="bg-white mx-4 mt-6 p-5 rounded-2xl shadow-sm">
        <h2 className="font-semibold mb-3">Earnings Overview</h2>

        <div className="flex items-end gap-2 h-32">
          {[2000, 4000, 3000, 5000, 3500, 6000].map((val, i) => (
            <div
              key={i}
              className="flex-1 bg-green-500 rounded-t-lg"
              style={{ height: `${val / 60}px` }}
            ></div>
          ))}
        </div>

        <div className="flex justify-between text-xs text-gray-400 mt-2">
          <span>Mon</span>
          <span>Tue</span>
          <span>Wed</span>
          <span>Thu</span>
          <span>Fri</span>
          <span>Sat</span>
        </div>
      </div>

      {/* 🔥 SCHEDULE FORM */}
      <div className="bg-white mx-4 mt-6 p-5 rounded-2xl shadow-sm">
        <h2 className="font-semibold mb-4">Schedule Pickup</h2>

        <div className="flex flex-col gap-3">
          <input type="date" className="input" />
          <input type="time" className="input" />

          <select className="input">
            <option>Select trash type</option>
            <option>Plastic</option>
            <option>Metal</option>
            <option>Glass</option>
            <option>Organic</option>
          </select>

          <button className="bg-green-600 text-white py-2 rounded-xl font-semibold hover:bg-green-700 transition">
            Confirm Pickup
          </button>
        </div>
      </div>

      {/* 🔥 PRICING */}
      <div id="pricing" className="bg-white mx-4 mt-6 p-5 rounded-2xl shadow-sm">
        <h2 className="font-semibold mb-3">Trash Pricing</h2>

        <div className="space-y-2 text-sm">
          <div className="flex justify-between">
            <span>Can Trash</span>
            <span className="text-green-600 font-semibold">₦500/kg</span>
          </div>
          <div className="flex justify-between">
            <span>Paper Trash</span>
            <span className="text-green-600 font-semibold">₦300/kg</span>
          </div>
          <div className="flex justify-between">
            <span>Glass Trash</span>
            <span className="text-green-600 font-semibold">₦200/kg</span>
          </div>
          <div className="flex justify-between">
            <span>Organic Trash</span>
            <span className="text-green-600 font-semibold">₦100/kg</span>
          </div>
        </div>
      </div>

      {/* 🔥 HISTORY */}
      <div id="history" className="bg-white mx-4 mt-6 p-5 rounded-2xl shadow-sm">
        <h2 className="font-semibold mb-3">Pickup History</h2>

        {pickups.length === 0 ? (
          <p className="text-gray-500 text-sm">No pickups yet.</p>
        ) : (
          <div className="flex flex-col gap-3">
            {pickups.map((item, i) => (
              <div key={i} className="flex justify-between border-b pb-2">
                <div>
                  <p className="font-medium">{item.type}</p>
                  <p className="text-sm text-gray-500">{item.date}</p>
                </div>

                <span className="text-green-600 font-semibold">
                  {item.kg}kg
                </span>
              </div>
            ))}
          </div>
        )}
      </div>

    </div>
  );
}